 it.each(['gap','provider','topology','producer','missing-bus','nonadjacent'])('keeps %s timing contexts unknown',kind=>{const p=projector();consume(p,model(1,0));if(kind==='missing-bus')consume(p,model(2,0,{buses:[]}));const packet=model(kind==='gap'?4:kind==='missing-bus'?3:2,kind==='nonadjacent'?2:1,{id:kind==='provider'?8:7,epoch:kind==='producer'?'next':'model',head:kind==='topology'?{topologySha256:'b'.repeat(64)}:{}});consume(p,packet);expect(p.records.filter(r=>r.kind==='model-projection').at(-1).buses[0].entry).toBeNull();expect(p.counts.clockEntries).toBe(0);});
