describe('read-only streaming original gzip prefixes',()=>{
 it('retains complete lines from an open sync-flushed stream and resumes after a partial final line',async()=>{const file=path.join(temporary(),'feed.gz'),gzip=createGzip(),sink=fs.createWriteStream(file);gzip.pipe(sink);gzip.write('{"a":"🚌"}\n{"b":');await new Promise((resolve,reject)=>gzip.flush(constants.Z_SYNC_FLUSH,e=>e?reject(e):resolve()));await new Promise((resolve,reject)=>sink.write('',e=>e?reject(e):resolve()));const first=await records(file);expect(first[0].record).toEqual({a:'🚌'});expect(first.at(-1).prefix.partialTail).toBe(true);gzip.write('2}\n');await new Promise((resolve,reject)=>gzip.flush(constants.Z_SYNC_FLUSH,e=>e?reject(e):resolve()));await new Promise((resolve,reject)=>sink.write('',e=>e?reject(e):resolve()));const next=await records(file,{previous:first.at(-1).prefix});expect(next.filter(r=>r.record).map(r=>r.record)).toEqual([{a:'🚌'},{b:2}]);gzip.end();await once(sink,'finish');});
 it('pins the captured prefix despite a concurrently appended new gzip member',async()=>{const file=path.join(temporary(),'feed.gz');fs.writeFileSync(file,gzipSync('{"a":1}\n'));const size=fs.statSync(file).size;fs.appendFileSync(file,gzipSync('{"a":2}\n'));const all=await records(file,{captureBytes:size});expect(all.filter(r=>r.record)).toHaveLength(1);expect(all.at(-1).prefix.bytes).toBe(size);});
 it('detects replaced/truncated prefixes and bounds decompression and complete line size',async()=>{const file=path.join(temporary(),'feed.gz');fs.writeFileSync(file,gzipSync('{"a":1}\n'));const prefix=(await records(file)).at(-1).prefix;fs.writeFileSync(file,gzipSync('{"a":2}\n'));await expect(records(file,{previous:prefix})).rejects.toThrow('prefix');await expect(records(file,{maxRawBytes:2})).rejects.toThrow('decompression');await expect(records(file,{maxLineBytes:2})).rejects.toThrow('record');});
 it('accepts an empty just-created hour and refuses symlinks',async()=>{const dir=temporary(),file=path.join(dir,'zero');fs.writeFileSync(file,'');expect((await records(file))[0].prefix.bytes).toBe(0);fs.symlinkSync(file,path.join(dir,'link'));await expect(records(path.join(dir,'link'))).rejects.toThrow('Invalid');});
 it('reads every concatenated gzip member after a recorder restart',async()=>{const file=path.join(temporary(),'concat.gz');fs.writeFileSync(file,Buffer.concat([gzipSync('{"a":1}\n'),gzipSync('{"a":2}\n')]));expect((await records(file)).filter(r=>r.record).map(r=>r.record.a)).toEqual([1,2]);});
});

describe('causal compact collector records',()=>{
 it('preserves exact source mutations and distinguishes departure from first availability',()=>{const f=collectorFixture();f.add();f.add({transit:{fromIndex:1,departedAt:base+5000}});const json=witnessJSON({id:3,route_id:10,leg_sec:123.456789});f.add({transit:{fromIndex:1,departedAt:base+5000},mutations:[{table:'legs',afterJSON:json,afterSHA256:witnessSHA(json)}]});const p=new CollectorProjection();p.consume(snapshot(f));const records=p.records.filter(r=>r.kind==='collector-projection');expect(records[1].buses[0].clock).toMatchObject({departedAt:base+5000,knownAt:base+10000,leftCensored:false});expect(records.at(-1).mutations[0].afterJSON).toBe(json);});
 it('resets clocks on a real input-write fence gap',()=>{const f=collectorFixture();f.add({transit:{fromIndex:1,departedAt:base}});f.add({transit:{fromIndex:1,departedAt:base},fence:false});const p=new CollectorProjection();p.consume(snapshot(f));const b=p.records.filter(r=>r.kind==='collector-projection').at(-1).buses[0];expect(b.clock.knownAt).toBe(base+10000);expect(b.clock.leftCensored).toBe(true);expect(p.counts.boundaries).toBe(2);});
 it('attaches a late original model source without backfilling a past causal clock',()=>{const f=collectorFixture();f.add({transit:{fromIndex:1,departedAt:base}});const first=new CollectorProjection();first.consume(snapshot(f));const late=new CollectorProjection(first.state,new Set(['collector:1']));late.consume(snapshot(f));const r=late.records[0];expect(r.selection).toBe('late-model-reference');expect(r.buses[0].clock).toBeNull();expect(late.state).toEqual(first.state);expect(late.required.size).toBe(0);});
 it('refuses corrupted pages rather than advancing',()=>{const f=collectorFixture();f.add();const s=snapshot(f);s.chunks[0].payload=gzipSync('{}');expect(()=>new CollectorProjection().consume(s)).toThrow('page');});
 it('refuses a source mutation whose whole frame is valid but whose returned row hash differs',()=>{const f=collectorFixture();f.add({mutations:[{table:'legs',afterJSON:witnessJSON({id:1}),afterSHA256:h}]});expect(()=>new CollectorProjection().consume(snapshot(f))).toThrow('row');});
 it('refuses corrupt original topology commitments',()=>{const f=collectorFixture();f.add();const s=snapshot(f);s.topologies.get(f.t.sha256).json+=' ';expect(()=>new CollectorProjection().consume(s)).toThrow('Topology');});
});

describe('independent rolling history storage and supervision',()=>{
 it('commits unavailable GPS without advancing the model clock and recovers after a later original forecast',async()=>{
  const f=collectorFixture(),first=f.add(),collectorDir=temporary(),learning=temporary(),cycle=path.join(learning,'cycle-1');fs.mkdirSync(cycle);
  const witness=new WitnessStore(collectorDir,{policy:{minFreeBytes:0}});stores.push(witness);const head=()=>({...f.journal.head(f.at),build:'build',evaluationEpoch:'model',evaluationCursor:1});witness.updateReports([],{now:f.at});witness.beginEpoch(head(),'test',f.at);witness.commitPage(f.page(),{seenHead:head(),now:f.at});
  const frozen=JSON.stringify({id:'cycle-1',sourceKey:h,productionBuild:'build'});fs.writeFileSync(path.join(cycle,'frozen-candidate.json'),frozen);fs.writeFileSync(path.join(learning,'state.json'),JSON.stringify({id:'cycle-1',forecastProtocol:'served-control-v2',sourceKey:h,frozenCandidateSha256:witnessSHA(frozen)}));
  const status=()=>fs.writeFileSync(path.join(learning,'status.json'),JSON.stringify({cycle:'cycle-1',running:true,feedReceivedAt:new Date(f.at).toISOString()}));status();
  const file=path.join(cycle,'feed-2026-10-21-04-1.jsonl.gz'),firstModel=model(1,0,{at:f.at,topo:f.t,head:{seq:first.seq,at:f.at,sha256:first.sha256}});fs.writeFileSync(file,gzipSync(JSON.stringify({source:firstModel})+'\n'));
  const s=history(),initial=await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at}),old=s.db.prepare('SELECT id,raw_sha FROM chunks').all();expect(initial.ok).toBe(true);
  f.add({at:base+3600000});witness.commitPage(f.page(1),{seenHead:head(),now:f.at});status();const receipt=missingFeed(f.at);fs.appendFileSync(file,gzipSync(JSON.stringify({receivedAt:f.at,source:receipt})+'\n'));
  const result=await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at});expect(result).toMatchObject({ok:true,forecastUnavailable:true,idleService:false,modelAt:first.at});expect(inspectTimingHistory(result,f.at)).toEqual([]);expect(s.state().model.tracks).toEqual({});for(const c of old)expect(s.db.prepare('SELECT raw_sha FROM chunks WHERE id=?').get(c.id).raw_sha).toBe(c.raw_sha);
  const again=await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at});expect(again.unchangedFiles).toBe(1);expect(again.forecastUnavailable).toBe(true);
  const latest=f.add({at:base+3605000});witness.commitPage(f.page(2),{seenHead:head(),now:f.at});status();fs.appendFileSync(file,gzipSync(JSON.stringify({source:model(2,1,{at:f.at,topo:f.t,head:{seq:latest.seq,at:f.at,sha256:latest.sha256}})})+'\n'));
  const recovered=await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at});expect(recovered).toMatchObject({ok:true,forecastUnavailable:false,idleService:false,modelAt:f.at});expect(recovered.forecastUnavailableReceipt).toBeUndefined();const rows=s.db.prepare('SELECT id FROM chunks ORDER BY at,id').all().flatMap(c=>s.read(c.id).records);expect(rows.filter(r=>r.kind==='forecast-unavailable-feed-receipt')).toHaveLength(1);expect(rows.filter(r=>r.kind==='model-projection').at(-1).buses[0].entry).toBeNull();
 });
 it('atomically commits a cold capture spanning several bounded chunks, including rollback of a later chunk',()=>{const s=history(),records=Array.from({length:6},(_,i)=>({at:base+i,value:'x'.repeat(1024*1024)}));s.db.exec("CREATE TRIGGER fault BEFORE INSERT ON chunks WHEN(SELECT count(*) FROM chunks)>0 BEGIN SELECT RAISE(ABORT,'later chunk fault');END");expect(()=>s.commit({records,state:{cursor:6},now:base})).toThrow('later chunk');expect(s.state()).toEqual({});expect(s.db.prepare('SELECT count(*) n FROM chunks').get().n).toBe(0);s.db.exec('DROP TRIGGER fault');const r=s.commit({records,state:{cursor:6},now:base});expect(r.chunkIds.length).toBeGreaterThan(1);expect(r.chunkIds.flatMap(id=>s.read(id).records)).toEqual(records);expect(s.state().cursor).toBe(6);});
 it('captures exact original model/source bindings, survives polling again and refuses a mismatched named source',async()=>{
  const f=collectorFixture(),first=f.add(),second=f.add(),collectorDir=temporary(),learning=temporary(),cycle=path.join(learning,'cycle-1');fs.mkdirSync(cycle);
  const witness=new WitnessStore(collectorDir,{policy:{minFreeBytes:0}});stores.push(witness);const head=()=>({...f.journal.head(f.at),build:'build',evaluationEpoch:'model',evaluationCursor:2});witness.updateReports([],{now:f.at});witness.beginEpoch(head(),'test',f.at);witness.commitPage(f.page(),{seenHead:head(),now:f.at});
  const frozen=JSON.stringify({id:'cycle-1',sourceKey:h,productionBuild:'build'});fs.writeFileSync(path.join(cycle,'frozen-candidate.json'),frozen);fs.writeFileSync(path.join(learning,'state.json'),JSON.stringify({id:'cycle-1',forecastProtocol:'served-control-v2',sourceKey:h,frozenCandidateSha256:witnessSHA(frozen)}));
  const status=()=>fs.writeFileSync(path.join(learning,'status.json'),JSON.stringify({cycle:'cycle-1',running:true,feedReceivedAt:new Date(f.at).toISOString()}));status();
  const packet=(frame,lead,extra={})=>model(frame.seq,lead,{at:frame.at,topo:f.t,head:{seq:frame.seq,at:frame.at,sha256:frame.sha256,...extra}});
  const file=path.join(cycle,'feed-2026-10-21-04-1.jsonl.gz');fs.writeFileSync(file,gzipSync([packet(first,0),packet(second,1)].map(source=>JSON.stringify({source})).join('\n')+'\n'));
  const s=history(),rawSource=fs.readFileSync(file),collectorSHA=witnessSHA(fs.readFileSync(witness.file));const result=await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at});expect(result.ok).toBe(true);expect(result.pendingSourceAssociations).toBe(0);expect(s.state().model.last.cursor).toBe(2);expect(fs.readFileSync(file)).toEqual(rawSource);expect(witnessSHA(fs.readFileSync(witness.file))).toBe(collectorSHA);
  const chunks=s.db.prepare('SELECT id FROM chunks').all().flatMap(r=>s.read(r.id).records),models=chunks.filter(r=>r.kind==='model-projection');expect(models[1].buses[0].entry.previousCursor).toBe(1);expect(models[1].buses[0].forecasts[0].quantiles).toHaveLength(50);expect((await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at})).unchangedFiles).toBe(1);
  const prior=s.state();s.db.prepare("UPDATE meta SET json=? WHERE key='state'").run(JSON.stringify({...prior,archiveSourceKey:h}));await collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at});expect(s.state().model.tracks).toEqual({});expect(s.state().archiveSourceKey).not.toBe(h);expect(s.db.prepare('SELECT id FROM chunks').all().flatMap(r=>s.read(r.id).records).some(r=>r.kind==='history-boundary')).toBe(true);
  const third=f.add();witness.commitPage(f.page(2),{seenHead:head(),now:f.at});status();fs.appendFileSync(file,gzipSync(JSON.stringify({source:packet(third,2,{sha256:'b'.repeat(64)})})+'\n'));const saved=s.state();await expect(collectHistory({store:s,learningRoot:learning,collectorFile:witness.file,now:f.at})).rejects.toThrow('Named collector');expect(s.state()).toEqual(saved);
 });
 it('commits records and cursor atomically and recovers after a failed SQL write',()=>{const s=history(),a=s.commit({records:[{at:base,kind:'test',value:1}],state:{cursor:1},now:base});s.db.exec("CREATE TRIGGER fault BEFORE INSERT ON meta BEGIN SELECT RAISE(ABORT,'test fault');END");expect(()=>s.commit({records:[{at:base+1,kind:'test'}],state:{cursor:2},now:base+1})).toThrow('test fault');expect(s.state()).toEqual({cursor:1});expect(s.read(a.id).records[0].value).toBe(1);expect(s.db.prepare('SELECT count(*) n FROM chunks').get().n).toBe(1);s.db.exec('DROP TRIGGER fault');s.commit({records:[{at:base+1,kind:'test'}],state:{cursor:2},now:base+1});expect(s.state().cursor).toBe(2);});
 it('physically rolls old routine history while keeping the current cursor',()=>{const s=history({maxAgeMs:1000}),a=s.commit({records:[{at:base,kind:'test',bytes:randomBytes(80000).toString('base64')}],state:{cursor:1},now:base});const bytes=s.disk().bytes;s.commit({records:[{at:base+2000,kind:'test'}],state:{cursor:2},now:base+2000});expect(()=>s.read(a.id)).toThrow('unavailable');expect(s.state().cursor).toBe(2);expect(s.disk().bytes).toBeLessThan(bytes);});
 it('bounds physical allocation and prunes only enough oldest routine chunks',()=>{const s=history({maxBytes:12*1024*1024});for(let i=0;i<16;i++)s.commit({records:[{at:base+i,kind:'test',bytes:randomBytes(300000).toString('base64')}],state:{cursor:i},now:base+i});expect(s.db.prepare('SELECT count(*) n FROM chunks').get().n).toBeGreaterThan(2);expect(s.db.prepare('SELECT count(*) n FROM chunks').get().n).toBeLessThan(16);expect(s.disk().bytes).toBeLessThan(s.policy.maxBytes);});
 it('holds on unknown files and oversized batches without advancing the cursor',()=>{const s=history();s.commit({records:[{at:base,kind:'test'}],state:{cursor:1},now:base});fs.writeFileSync(path.join(s.directory,'unknown.partial'),'preserve');expect(()=>s.commit({records:[],state:{cursor:2},now:base})).toThrow('Unknown');expect(s.state().cursor).toBe(1);fs.unlinkSync(path.join(s.directory,'unknown.partial'));expect(()=>s.commit({records:[{at:base,value:'x'.repeat(8*1024*1024)}],state:{cursor:2},now:base})).toThrow('bound');expect(s.state().cursor).toBe(1);});
 it('opens an exported closed database and detects modified projection bytes',()=>{const s=history(),r=s.commit({records:[{at:base,kind:'test'}],state:{cursor:1},now:base}),target=temporary();s.close();stores.splice(stores.indexOf(s),1);fs.copyFileSync(s.file,path.join(target,'history.sqlite'));const restored=new HistoryStore(target,{policy:{minFreeBytes:0}});stores.push(restored);expect(restored.state().cursor).toBe(1);expect(restored.read(r.id).records).toHaveLength(1);restored.db.prepare('UPDATE chunks SET payload=?').run(gzipSync('{}'));expect(()=>restored.read(r.id)).toThrow('commitment');});
 it('recovers the committed cursor and record in an independent process',()=>{const s=history(),r=s.commit({records:[{at:base,kind:'test',value:42}],state:{cursor:123},now:base}),dir=s.directory;s.close();stores.splice(stores.indexOf(s),1);const module=new URL('./storage.mjs',import.meta.url).href,script=`import{HistoryStore}from ${JSON.stringify(module)};const s=new HistoryStore(${JSON.stringify(dir)},{policy:{minFreeBytes:0}});console.log(JSON.stringify({state:s.state(),record:s.read(${JSON.stringify(r.id)}).records[0]}));s.close();`;const result=JSON.parse(execFileSync(process.execPath,['--import','tsx','--input-type=module','-e',script],{encoding:'utf8'}));expect(result.state.cursor).toBe(123);expect(result.record.value).toBe(42);});
 it('refuses an output overlapping either source before creating files',async()=>{const source=temporary(),child=path.join(source,'would-write');await expect(runOnce({directory:child,learningRoot:source,collectorFile:path.join(temporary(),'source.sqlite')})).rejects.toThrow('separate');expect(fs.existsSync(child)).toBe(false);});
 it('independently detects a dead archive and stale inputs despite a fresh claimed heartbeat',()=>{const good={checkedAt:new Date(base).toISOString(),ok:true,modelAt:base,collectorAt:base};expect(inspectTimingHistory(good,base+19*60000)).toEqual([]);expect(inspectTimingHistory(good,base+21*60000).map(i=>i.code)).toEqual(['timing-history-heartbeat']);expect(inspectTimingHistory({...good,modelAt:base-180000},base).map(i=>i.code)).toEqual(['timing-history-capture']);let prior;for(let i=0;i<3;i++)prior=advance(prior,'cycle-1',inspectTimingHistory(null,base+i*60000),base+i*60000);expect(prior.alerts).toHaveLength(2);});
 it('accepts a verified fresh empty feed while refusing an idle flag alone',()=>{const idle={checkedAt:new Date(base).toISOString(),ok:true,modelAt:base-3600000,collectorAt:base,idleService:true,idleReceipt:{receivedAt:base,responseAt:base,recordSHA256:h,emptyFleet:true,hasServerEta:false}};expect(inspectTimingHistory(idle,base)).toEqual([]);expect(inspectTimingHistory({...idle,idleReceipt:null},base)).toHaveLength(1);expect(inspectTimingHistory({...idle,idleReceipt:{...idle.idleReceipt,responseAt:base-3600000}},base)).toHaveLength(1);});
 it('independently verifies original GPS observations before accepting forecast unavailability',()=>{const status={checkedAt:new Date(base).toISOString(),ok:true,modelAt:base-3600000,collectorAt:base,forecastUnavailable:true,forecastUnavailableReceipt:{receivedAt:base,responseAt:base,recordSHA256:h,emptyFleet:false,hasServerEta:false,freshGpsBuses:1,observations:[{busId:8,busName:'#unknown',routeId:999,observedAt:base,lat:41.3,lon:-72.9}]}};expect(inspectTimingHistory(status,base)).toEqual([]);for(const change of[{forecastUnavailableReceipt:null},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,observations:[]}},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,freshGpsBuses:2}},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,observations:[{...status.forecastUnavailableReceipt.observations[0],observedAt:base-45000}]}},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,observations:[{...status.forecastUnavailableReceipt.observations[0],observedAt:base+1}]}},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,responseAt:base-180000}},{forecastUnavailableReceipt:{...status.forecastUnavailableReceipt,recordSHA256:'invalid'}}])expect(inspectTimingHistory({...status,...change},base).map(i=>i.code)).toContain('timing-history-capture');});
});
